function plainTransformLayer(){const l=currentImageLayer();return canTransformImageLayer(l)&&!l.kind?l:null}
function syncImageTransformControls(){const l=plainTransformLayer();$('imageTransformControls').hidden=!l;if(!l)return;$('imageRotation').value=l.rotation||0;$('imageRotationValue').textContent=(l.rotation||0)+'°';$('imageCornerMode').setAttribute('aria-pressed',String(!!l.cornerMode));$('imageCornerMode').classList.toggle('active',!!l.cornerMode);$('imageCornerMode').textContent=l.cornerMode?'모서리 맞추기 완료':'모서리 맞추기'}
function initImageTransforms(){$('imageRotation').onfocus=()=>inputHistoryKey=null;$('imageRotation').oninput=()=>{const l=plainTransformLayer();if(projectBusy||!l)return;const angle=Math.max(-180,Math.min(180,Number($('imageRotation').value)||0));if(!validSocialQuad(socialQuad({...l,rotation:angle})))return;recordInput('imageRotation');l.rotation=angle;$('imageRotationValue').textContent=angle+'°';render()};$('imageRotation').onchange=()=>{inputHistoryKey=null;sync()};$('imageCornerMode').onclick=()=>{const l=plainTransformLayer();if(projectBusy||!l)return;checkpoint();l.cornerMode=!l.cornerMode;imageLayerEraser=false;sync()};$('imageTransformReset').onclick=()=>{const l=plainTransformLayer();if(projectBusy||!l)return;checkpoint();l.rotation=0;l.warpCorners=[[0,0],[0,0],[0,0],[0,0]];delete l.warpEdges;l.cornerMode=false;sync()}}
